def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find connected components of non-background cells.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if (0 <= nx < h and 0 <= ny < w and
                        (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            comps.append((color, cells))

    # Identify the prominent 7 L-shaped corner marker.
    marker = None
    for color, cells in comps:
        if color != 7:
            continue
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        if max(rs) == h-1 and max(cs) == w-1 and len(cells) >= 8:
            marker = cells
            break
    if marker is None:
        return out

    mr = sum(r for r, c in marker) / len(marker)
    mc = sum(c for r, c in marker) / len(marker)

    # Recolor the 3-component farthest from the marker.
    candidates = [(color, cells) for color, cells in comps if color == 3]
    if candidates:
        color, cells = max(
            candidates,
            key=lambda item: (
                (sum(r for r, c in item[1]) / len(item[1]) - mr) ** 2 +
                (sum(c for r, c in item[1]) / len(item[1]) - mc) ** 2
            )
        )
        for r, c in cells:
            out[r][c] = 7
    return out
